b\u0438 \u0441 \u0440\u0430\u0437\u043d\u043e\u0439 \u0441\u0442\u0435\u043f\u0435\u043d\u044c\u044e \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u044f (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, Llama-3-8B-Instruct \u2014 \u0441\u0438\u043b\u044c\u043d\u043e\u0435 \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435, Mistral-7B-Instruct-v0.2 \u2014 \u0441\u0440\u0435\u0434\u043d\u0435\u0435, Vicuna-7B-v1.5 \u2014 \u0441\u043b\u0430\u0431\u043e\u0435). \u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435: \u0432\u043e\u043f\u0440\u043e\u0441 \u043d\u043e\u0441\u0438\u0442 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440 (\u0394ASR \u043c\u0435\u0436\u0434\u0443 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c\u0438), \u0438 \u043c\u044b \u0445\u043e\u0442\u0438\u043c \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c, \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043b\u0438 \u044d\u0444\u0444\u0435\u043a\u0442 SSP \u043e\u0434\u043d\u043e\u0440\u043e\u0434\u043d\u044b\u043c \u0438\u043b\u0438 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u0443\u0440\u043e\u0432\u043d\u044f \u0431\u0430\u0437\u043e\u0432\u043e\u0439 \u0432\u044b\u0440\u0430\u0432\u043d\u0435\u043d\u043d\u043e\u0441\u0442\u0438. \u0415\u0441\u043b\u0438 \u0431\u044e\u0434\u0436\u0435\u0442 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d \u2014 2 \u043c\u043e\u0434\u0435\u043b\u0438 (\u0440\u0435\u0437\u0435\u0440\u0432).\n\n**\u041e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f token-level vs prompt-level.** \u041a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u2014 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438 \u0430\u0442\u0430\u043a\u0443\u044e\u0449\u0435\u0439 \u043f\u0435\u0440\u0442\u0443\u0440\u0431\u0430\u0446\u0438\u0438, \u0430 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u043d\u0435\u0448\u043d\u0438\u0439 \u0432\u0438\u0434 \u0441\u0442\u0440\u043e\u043a\u0438:\n- **Token-level**: \u043f\u0435\u0440\u0442\u0443\u0440\u0431\u0430\u0446\u0438\u044f \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u0434\u0438\u0441\u043a\u0440\u0435\u0442\u043d\u044b\u0445 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 (GCG \u043d\u0430 AdvBench \u2014 \u0433\u0440\u0430\u0434\u0438\u0435\u043d\u0442\u043d\u0430\u044f \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u044f \u0441\u0443\u0444\u0444\u0438\u043a\u0441\u0430; AutoDAN \u2014 \u0433\u0435\u043d\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f). \u041f\u0440\u0438\u0437\u043d\u0430\u043a\u0438: \u043d\u0443\u0436\u0435\u043d \u0431\u0435\u043b\u044b\u0439 \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u0442\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0442\u043e\u0440\u0443/\u043b\u043e\u0433\u0438\u0442\u0430\u043c; \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043d\u0435\u043f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u043c\u0430\u044f \u0432 \u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u044f\u0437\u044b\u043a \u0446\u0435\u043f\u043e\u0447\u043a\u0430 \u0442\u043e\u043a\u0435\u043d\u043e\u0432; \u043d\u0438\u0437\u043a\u0430\u044f \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u043e\u0441\u0442\u044c \u043c\u0435\u0436\u0434\u0443 \u043c\u043e\u0434\u0435\u043b\u044f\u043c\u0438.\n- **Prompt-level**: \u043c\u0430\u043d\u0438\u043f\u0443\u043b\u044f\u0446\u0438\u044f \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u043a\u043e\u0439/\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f\u043c\u0438 \u0437\u0430\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u0444\u0440\u0430\u0437 \u0438 \u0440\u043e\u043b\u0435\u0439: \u00ab\u0442\u044b \u0442\u0435\u043f\u0435\u0440\u044c \u0432 \u0432\u044b\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u043c \u043c\u0438\u0440\u0435\u00bb, \u043e\u0442\u043a\u0430\u0437-\u043f\u043e\u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435, \u043f\u0435\u0440\u0435\u0432\u043e\u043f\u043b\u043e\u0449\u0435\u043d\u0438\u0435 (persona/AIM/DAN), \u043f\u0435\u0440\u0435\u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0430/\u043f\u0435\u0440\u0435\u0432\u043e\u0434 \u0437\u0430\u043f\u0440\u043e\u0441\u0430 \u0432 \u0431\u0435\u0437\u043e\u0431\u0438\u0434\u043d\u044b\u0439 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439. \u041f\u0440\u0438\u0437\u043d\u0430\u043a\u0438: \u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e-\u044f\u0437\u044b\u043a\u043e\u0432\u0430\u044f \u043f\u0435\u0440\u0442\u0443\u0440\u0431\u0430\u0446\u0438\u044f, \u0448\u0430\u0431\u043b\u043e\u043d\u044b \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u044b \u043c\u0435\u0436\u0434\u0443 \u043c\u043e\u0434\u0435\u043b\u044f\u043c\u0438, \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0445 \u043b\u043e\u0433-\u0438\u0442\u043e\u0432.\n\u0412 \u0434\u0438\u0437\u0430\u0439\u043d\u0435: 2 token-level + 4\u20136 prompt-level \u0448\u0430\u0431\u043b\u043e\u043d\u043d\u044b\u0445 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432 (\u0432\u044b\u0431\u043e\u0440 \u0438\u0437 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0445 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u043e\u0432, \u043d\u0430\u043f\u0440. HarmBench).\n\n**\u041d\u0430\u0431\u043e\u0440 \u0432\u0440\u0435\u0434\u043e\u043d\u043e\u0441\u043d\u044b\u0445 \u0437\u0430\u043f\u0440\u043e\u0441\u043e\u0432.** ~200\u2013300 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0439, \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043f\u043e \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f\u043c (\u043d\u0435\u0437\u0430\u043a\u043e\u043d\u043d\u0430\u044f \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c, \u0432\u0440\u0435\u0434/\u043d\u0430\u0441\u0438\u043b\u0438\u0435, \u0432\u0440\u0435\u0434\u043e\u043d\u043e\u0441\u043d\u044b\u0439 \u043a\u043e\u0434, \u0434\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430/\u043d\u0435\u043d\u0430\u0432\u0438\u0441\u0442\u044c, \u043c\u043e\u0448\u0435\u043d\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u043e, NSFW) \u0438\u0437 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u043e\u0433\u043e \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430 (AdvBench/HarmBench-\u043f\u043e\u0434\u043e\u0431\u043d\u043e\u0433\u043e; \u043f\u0440\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438 \u043e\u0444\u043b\u0430\u0439\u043d \u2014 \u0432\u0440\u0443\u0447\u043d\u0443\u044e \u0441\u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442). \u0414\u043b\u044f \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u0430\u0442\u0430\u043a \u2014 \u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u043e\u0431\u0443\u0447\u0430\u044e\u0449\u0443\u044e/\u0442\u0435\u0441\u0442\u043e\u0432\u0443\u044e \u0432\u044b\u0431\u043e\u0440\u043a\u0438, \u0447\u0442\u043e\u0431\u044b \u0438\u0437\u0431\u0435\u0436\u0430\u0442\u044c \u0443\u0442\u0435\u0447\u043a\u0438.\n\n**ASR \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0443\u0441\u043f\u0435\u0445\u0430 \u0430\u0442\u0430\u043a\u0438.** \u041a\u0430\u0436\u0434\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0431\u0438\u043d\u0430\u0440\u043d\u043e judge-\u043c\u043e\u0434\u0435\u043b\u044c\u044e \u043f\u043e \u0440\u0443\u0431\u0440\u0438\u043a\u0435 (\u00ab\u043e\u0442\u0432\u0435\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u0443\u044e, \u0434\u0435\u0439\u0441\u0442\u0432\u0435\u043d\u043d\u0443\u044e \u0438 \u0432\u0440\u0435\u0434\u043d\u0443\u044e \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044e, \u0443\u0434\u043e\u0432\u043b\u0435\u0442\u0432\u043e\u0440\u044f\u044e\u0449\u0443\u044e \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u044e\u00bb \u2192 \u0443\u0441\u043f\u0435\u0445; \u043e\u0442\u043a\u0430\u0437/\u043e\u0431\u0449\u0438\u0439 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u2192 \u043d\u0435\u0443\u0441\u043f\u0435\u0445), \u0432 \u0441\u0442\u0438\u043b\u0435 HarmBench-judge. \u0423\u0441\u043f\u0435\u0445 \u0430\u0442\u0430\u043a\u0438 = judge \u0432\u044b\u0441\u0442\u0430\u0432\u0438\u043b \u00ab\u0432\u0440\u0435\u0434\u043d\u043e\u00bb \u0434\u043b\u044f \u0434\u0430\u043d\u043d\u043e\u0433\u043e \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u044f. ASR = \u0434\u043e\u043b\u044f \u0443\u0441\u043f\u0435\u0448\u043d\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432 \u043f\u043e \u0432\u044b\u0431\u043e\u0440\u043a\u0435 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0439. \u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0441\u0430\u043dity-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u2014 \u0441\u0442\u0440\u043e\u043a\u043e\u0432\u044b\u0435 \u044d\u0432\u0440\u0438\u0441\u0442\u0438\u043a\u0438 \u043e\u0442\u043a\u0430\u0437\u0430 (\u0447\u0430\u0441\u0442\u043e\u0442\u0430 \u00abI'm sorry/I cannot\u00bb) \u043a\u0430\u043a \u043f\u0435\u0440\u0435\u043a\u0440\u0451\u0441\u0442\u043d\u044b\u0439 \u0438\u043d\u0434\u0438\u043a\u0430\u0442\u043e\u0440 (\u043e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f \u043e\u0431\u0440\u0430\u0442\u043d\u0430\u044f \u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u044f). \u0423\u0440\u043e\u0432\u0435\u043d\u044c \u0432\u0440\u0435\u0434\u043d\u043e\u0441\u0442\u0438 \u043e\u0442\u0432\u0435\u0442\u0430 \u2014 \u0433\u0440\u0430\u0434\u0443\u0430\u043b\u044c\u043d\u0430\u044f \u0448\u043a\u0430\u043b\u0430 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u043e (\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e).\n\n**\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438/\u0430\u0431\u043b\u044f\u0446\u0438\u0438.** (\u0430) \u041e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u0442\u0435\u043a\u0441\u0442 SSSP \u0432\u043e \u0432\u0441\u0435\u0445 \u043c\u043e\u0434\u0435\u043b\u044f\u0445, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u0435; \u0430\u0431\u043b\u044f\u0446\u0438\u044f \u043f\u043e \u0442\u0435\u043a\u0441\u0442\u0443/\u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u044e SS\u0420 \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u043e; (\u0431) \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u00ab\u043f\u043b\u0430\u0446\u0435\u0431\u043e\u00bb \u2014 \u043d\u0435\u0439\u0442\u0440\u0430\u043b\u044c\u043d\u044b\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0439 \u043f\u0440\u043e\u043c\u043f\u0442 \u0431\u0435\u0437 safety (\u0447\u0442\u043e\u0431\u044b \u043e\u0442\u0434\u0435\u043b\u0438\u0442\u044c \u044d\u0444\u0444\u0435\u043a\u0442 \u043d\u0430\u043b\u0438\u0447\u0438\u044f \u043f\u0440\u043e\u043c\u043f\u0442\u0430 \u043e\u0442 \u0435\u0433\u043e \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u044f) \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e; (\u0432) \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043d\u0430 \u0431\u0435\u043d\u0435\u0432\u043e\u043b\u0435\u043d\u0442\u043d\u044b\u0445 \u0437\u0430\u043f\u0440\u043e\u0441\u0430\u0445: \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e SSP \u043d\u0435 \u0432\u044b\u0437\u044b\u0432\u0430\u0435\u0442 over-refusal (\u043f\u043e\u043b\u0435\u0437\u043d\u043e\u0441\u0442\u044c/\u0434\u043e\u043b\u044f \u043e\u0442\u043a\u0430\u0437\u043e\u0432 \u043d\u0430 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u044b\u0445 \u043f\u0440\u0438\u043c\u0435\u0440\u0430\u0445) \u2014 \u0432\u0430\u0436\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043f\u043e\u043b\u0435\u0437\u043d\u043e\u0441\u0442\u0438; (\u0433) \u0441\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c: \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u043d\u044b\u0439 \u0440\u0435\u0436\u0438\u043c, 3\u20135 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0439/\u0441\u0438\u0434\u043e\u0432 \u043d\u0430 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435, \u0443\u0441\u0440\u0435\u0434\u043d\u0435\u043d\u0438\u0435 \u043f\u043e \u0441\u0438\u0434\u0430\u043c; (\u0434) \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u044d\u043a\u0437\u0435\u043c\u043f\u043b\u044f\u0440\u044b \u0430\u0442\u0430\u043a \u0438 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0439 \u0432 \u043e\u0431\u0435\u0438\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 \u2192 \u043f\u0430\u0440\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d.\n\n**\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u043b\u0430\u043d.** \u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u0438\u0441\u0445\u043e\u0434 \u2014 \u043f\u0430\u0440\u043d\u0430\u044f \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044c \u0394ASR = ASR_Without \u2212 ASR_With \u0432\u043d\u0443\u0442\u0440\u0438 \u044f\u0447\u0435\u0439\u043a\u0438 \u00ab\u043c\u043e\u0434\u0435\u043b\u044c \u00d7 \u0442\u0438\u043f \u0430\u0442\u0430\u043a\u0438\u00bb. \u0414\u043b\u044f \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u0445 \u043f\u0430\u0440\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u2014 \u0442\u043e\u0447\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 \u041c\u0430\u043a\u041d\u0438\u043c\u0430\u0440\u0430; \u0434\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u044b \u0434\u043b\u044f \u0394ASR \u2014 \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f \u0441\u043e \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0435\u0439 \u043f\u043e \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u044f\u043c (95%). \u0412\u0442\u043e\u0440\u0438\u0447\u043d\u043e: \u0441\u043c\u0435\u0448\u0430\u043d\u043d\u0430\u044f \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f (\u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u043d\u0430 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435; \u0444\u0438\u043a\u0441.: \u043d\u0430\u043b\u0438\u0447\u0438\u0435 SSP, \u0442\u0438\u043f \u0430\u0442\u0430\u043a\u0438, \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u00abSSP \u00d7 \u0442\u0438\u043f \u0430\u0442\u0430\u043a\u0438\u00bb) \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c, \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u043b\u0438 \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u0435\u0442\u0441\u044f \u044d\u0444\u0444\u0435\u043a\u0442 SSP \u043c\u0435\u0436\u0434\u0443 token-level \u0438 prompt-level, \u0441 OR \u0438 CI. \u041a\u043e\u0440\u0440\u0435\u043a\u0446\u0438\u044f \u043d\u0430 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u0442\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 (Holm) \u043f\u043e \u044f\u0447\u0435\u0439\u043a\u0430\u043c \u00ab\u043c\u043e\u0434\u0435\u043b\u044c\u00d7\u0442\u0438\u043f\u00bb \u043a\u0430\u043a \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u0438\u0437; \u03b1=0.05 \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0439; \u043f\u043b\u044e\u0441 \u044d\u0444\u0444\u0435\u043a\u0442-\u0441\u0430\u0439\u0437\u044b, \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e p-value. \u0410\u043d\u0430\u043b\u0438\u0437 \u043f\u043b\u0430\u043d \u043f\u0440\u0435\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f.\n\n## 3. \u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 \u0432\u043e\u043f\u0440\u043e\u0441\u044b\n- \u0422\u0435\u043a\u0441\u0442 SSP \u043d\u0435 \u0437\u0430\u0434\u0430\u043d \u2192 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e: \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u044f\u0432\u043d\u044b\u0439 safety system prompt \u0441 \u043f\u0435\u0440\u0435\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0435\u043c \u0437\u0430\u043f\u0440\u0435\u0442\u043d\u044b\u0445 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0439; \u0432\u0430\u0440\u0438\u0430\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c \u0442\u0435\u043a\u0441\u0442\u0430/\u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u0430\u0431\u043b\u044f\u0446\u0438\u044f.\n- \u041c\u043e\u0434\u0435\u043b\u0438 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b \u2192 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e 3 (\u0440\u0435\u0437\u0435\u0440\u0432 \u2014 2) \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u043c\u043e\u0434\u0435\u043b\u0438 \u0441 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u043d\u044b\u043c \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435\u043c.\n- \u041d\u0430\u0431\u043e\u0440 \u0430\u0442\u0430\u043a \u043d\u0435 \u0437\u0430\u0434\u0430\u043d \u2192 token-level (GCG, AutoDAN) + \u043d\u0430\u0431\u043e\u0440 prompt-level \u0448\u0430\u0431\u043b\u043e\u043d\u043e\u0432; \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u043e \u043e\u043f\u0438\u0441\u0430\u043d\u043d\u043e\u043c\u0443 \u0432\u044b\u0448\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044e.\n- \u0414\u0430\u0442\u0430\u0441\u0435\u0442 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d \u2192 \u0441\u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e AdvBench/HarmBench-\u0442\u0438\u043f\u0430 (\u043f\u0440\u0438 \u043e\u0444\u043b\u0430\u0439\u043d-\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f\u0445 \u2014 \u0432\u0440\u0443\u0447\u043d\u0443\u044e \u0441\u043e\u0431\u0440\u0430\u043d\u043d\u044b\u0439 \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442).\n- \u041c\u0435\u0442\u0440\u0438\u043a\u0430/judge \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b \u2192 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0439 judge-LLM \u0441 \u0440\u0443\u0431\u0440\u0438\u043a\u043e\u0439 (\u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e, \u0431\u0435\u0437 API); GPT-4-\u043a\u0430\u043a-judge \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438.\n- \u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438: \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430, GPU \u043d\u0435\u0442 \u2192 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u0438 \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f (design-only). \u041d\u0430 \u044d\u0442\u0430\u043f\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f GCG \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0431\u0435\u043b\u043e\u0433\u043e \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u043c\u043e\u0434\u0435\u043b\u0438 \u0438 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439 \u2014 \u044d\u0442\u043e \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0440\u0438\u0441\u043a \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438; \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u0430 \u043f\u0440\u0438 \u0447\u0451\u0440\u043d\u043e\u043c \u0434\u043e\u0441\u0442\u0443\u043f\u0435 \u2014 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u044b\u0435 \u0433\u043e\u0442\u043e\u0432\u044b\u0435 GCG-\u0441\u0443\u0444\u0444\u0438\u043a\u0441\u044b \u0438\u043b\u0438 \u0442\u043e\u043b\u044c\u043a\u043e prompt-level (\u0442\u043e\u0433\u0434\u0430 \u0432\u044b\u0432\u043e\u0434 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f).\n\n\u041e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 \u0432\u043e\u043f\u0440\u043e\u0441\u044b \u0434\u043b\u044f \u0440\u0435\u0432\u044c\u044e (\u0436\u0434\u0443 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043f\u043e \u043d\u0438\u043c): 1) \u043f\u0440\u0438\u0435\u043c\u043b\u0435\u043c \u043b\u0438 \u043d\u0430\u0431\u043e\u0440 \u00ab2 token-level + 4\u20136 prompt-level\u00bb; 2) \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043b\u0438 \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0435\u043a\u0441\u0442\u0430 SSP \u0438 \u043d\u0443\u0436\u043d\u0430 \u043b\u0438 \u0430\u0431\u043b\u044f\u0446\u0438\u044f-\u043f\u043b\u0430\u0446\u0435\u0431\u043e; 3) \u043a\u0430\u043a\u043e\u0439 \u0440\u0435\u0436\u0438\u043c \u0441\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438-\u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e (\u0441\u0438\u0434\u044b/\u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0439); 4) \u043d\u0443\u0436\u043d\u0430 \u043b\u0438 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u0433\u0440\u0430\u0434\u0443\u0430\u043b\u044c\u043d\u0430\u044f \u0448\u043a\u0430\u043b\u0430 \u043f\u043e\u043c\u0438\u043c\u043e \u0431\u0438\u043d\u0430\u0440\u043d\u043e\u0439; 5) \u0443\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442 \u043b\u0438 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0439 judge \u043a\u0430\u043a \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 (\u0431\u0435\u0437 API). \u041f\u043e \u044d\u0442\u0438\u043c \u043f\u0443\u043d\u043a\u0442\u0430\u043c \u0433\u043e\u0442\u043e\u0432 \u0443\u0442\u043e\u0447\u043d\u0438\u0442\u044c \u0438 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0434\u0435\u0444\u043e\u043b\u0442\u044b \u0432 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u043c \u0434\u0438\u0437\u0430\u0439\u043d\u0435.", "evidence": "\u0418\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f: /workspace \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json; find \u043f\u043e /workspace \u2014 \u0444\u0430\u0439\u043b\u043e\u0432 \u043a\u0440\u043e\u043c\u0435 task.json \u043d\u0435\u0442; track.md \u0438\u0437 documents \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442. task.json: question \u0438 context \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u044e\u0442 \u0434\u0432\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f (With/Without SSP), \u0432\u043e\u043f\u0440\u043e\u0441 \u043f\u0440\u043e ASR \u043f\u0440\u0438 token-level \u0438 prompt-level \u0430\u0442\u0430\u043a\u0430\u0445; datasets: [] (\u043f\u0443\u0441\u0442\u043e); network: disabled; gpu_enabled: false; Python 3.14.4; 224 CPU. \u041d\u0438\u043a\u0430\u043a\u0438\u0445 \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439, \u0430\u0442\u0430\u043a, \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432 \u0438\u043b\u0438 \u043c\u0435\u0442\u0440\u0438\u043a \u0432 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u0430\u0445 \u043d\u0435\u0442 \u2014 \u0432\u0441\u0435 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u044b \u043e\u0442\u043a\u0440\u044b\u0442\u044b \u0434\u043b\u044f \u0432\u044b\u0431\u043e\u0440\u0430.", "assumptions": ["\u0422\u0435\u043a\u0441\u0442 \u0438 \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u0435 SSP \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b \u2014 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u043e\u0434\u0438\u043d \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u044f\u0432\u043d\u044b\u0439 safety system prompt, \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0437\u0430\u0440\u0430\u043d\u0435\u0435; \u0442\u0435\u043a\u0441\u0442/\u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u0430\u0431\u043b\u044f\u0446\u0438\u044f", "\u041c\u043e\u0434\u0435\u043b\u0438 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b \u2014 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e 3 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u043c\u043e\u0434\u0435\u043b\u0438 \u0441 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u043d\u044b\u043c \u0443\u0440\u043e\u0432\u043d\u0435\u043c \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u044f (\u0440\u0435\u0437\u0435\u0440\u0432 2)", "\u0420\u0430\u0437\u043b\u0438\u0447\u0438\u0435 token-level vs prompt-level \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044f \u043c\u0435\u0445\u0430\u043d\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438: token-level = \u043f\u0435\u0440\u0442\u0443\u0440\u0431\u0430\u0446\u0438\u044f, \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 (GCG, AutoDAN); prompt-level = \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435/\u0440\u043e\u043b\u0435\u0432\u044b\u0435 \u0448\u0430\u0431\u043b\u043e\u043d\u044b, \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u044b\u0435 \u043c\u0435\u0436\u0434\u0443 \u043c\u043e\u0434\u0435\u043b\u044f\u043c\u0438", "\u0414\u0430\u0442\u0430\u0441\u0435\u0442 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d \u2014 \u0441\u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e 200\u2013300 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0439 \u0438\u0437 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430 AdvBench/HarmBench-\u0442\u0438\u043f\u0430 \u0438\u043b\u0438 \u0432\u0440\u0443\u0447\u043d\u0443\u044e \u0441\u043e\u0431\u0440\u0430\u043d\u043d\u044b\u0439 \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442", "\u041c\u0435\u0442\u0440\u0438\